namespace SrpLab;
public sealed class ClinicBusinessHoursPolicy { public bool IsWithin(DateTimeOffset when,TimeOnly open,TimeOnly close,int minutes){if(when.DayOfWeek is DayOfWeek.Friday or DayOfWeek.Saturday)return false;var time=TimeOnly.FromDateTime(when.DateTime);return time>=open&&time.AddMinutes(minutes)<=close;} }
public sealed class AppointmentBookingCalendar { private readonly HashSet<DateTimeOffset> _booked=new(); public bool IsBooked(DateTimeOffset slot){return _booked.Contains(slot);} public bool Book(DateTimeOffset slot){if(_booked.Contains(slot))return false;_booked.Add(slot);return true;} }
public sealed class AppointmentSlotFinder { public DateTimeOffset? Find(DateTimeOffset from,int hours,int minutes,ClinicBusinessHoursPolicy policy,TimeOnly open,TimeOnly close,AppointmentBookingCalendar calendar){var aligned=new DateTimeOffset(from.Year,from.Month,from.Day,from.Hour,from.Minute-from.Minute%minutes,0,from.Offset);var end=from.AddHours(hours);while(aligned<end){if(policy.IsWithin(aligned,open,close,minutes)&&!calendar.IsBooked(aligned))return aligned;aligned=aligned.AddMinutes(minutes);}return null;} }
public sealed class IcsCalendarSerializer { public string Serialize(DateTimeOffset slot,int minutes,string patient,string clinician){var end=slot.AddMinutes(minutes);return "BEGIN:VCALENDAR\nVERSION:2.0\nBEGIN:VEVENT\n"+$"UID:{Guid.NewGuid()}\nDTSTART:{slot:yyyyMMdd'T'HHmmss'Z'}\nDTEND:{end:yyyyMMdd'T'HHmmss'Z'}\n"+$"SUMMARY:Visit {patient} / {clinician}\nEND:VEVENT\nEND:VCALENDAR\n";} }
public sealed class SmsReminderComposer { public string Compose(DateTimeOffset slot,string phone){return $"Reminder: appointment {slot:MMM dd HH:mm}. Call {phone} to reschedule.";} }
